import java.util.*;
import java.io.*;

public class Main {
    static int[][][][] shortestPath = new int[15][15][15][15];
    static int[][] capacityMatrix = new int[400][400];
    static char[][] scienceMap = new char[20][20];
    static char[][] reactionMap = new char[20][20];
    static int[] dirX = {1, 0, -1, 0};
    static int[] dirY = {0, 1, 0, -1};
    static int currentVisit = 3;
    static int[] visitedNodes = new int[400];
    static int n, tLimit;
    static int[][] reachStates = new int[13][13];
    static int[][] tempStates = new int[13][13];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int infX = 0, infY = 0;

        for (int i = 0; i < 15; i++) {
            for (int j = 0; j < 15; j++) {
                for (int k = 0; k < 15; k++) {
                    for (int l = 0; l < 15; l++) {
                        shortestPath[i][j][k][l] = 1000000000;
                    }
                }
            }
        }
        for (int i = 0; i < 400; i++) {
            Arrays.fill(capacityMatrix[i], 0);
        }

        String line = br.readLine();
        n = Integer.parseInt(line.trim());
        tLimit = Integer.parseInt(br.readLine().trim());

        for (int i = 1; i <= n; i++) {
            String row = br.readLine();
            for (int j = 1; j <= n; j++) {
                scienceMap[i][j] = row.charAt(j - 1);
                shortestPath[i][j][i][j] = 0;
                if (scienceMap[i][j] == 'Z') {
                    infX = i;
                    infY = j;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            String row = br.readLine();
            for (int j = 1; j <= n; j++) {
                reactionMap[i][j] = row.charAt(j - 1);
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                for (int d = 0; d < 4; d++) {
                    int ni = i + dirX[d], nj = j + dirY[d];
                    if (ni > 0 && ni <= n && nj > 0 && nj <= n) {
                        if (scienceMap[i][j] != 'Y' && scienceMap[ni][nj] != 'Y') {
                            shortestPath[i][j][ni][nj] = 1;
                        }
                    }
                }
            }
        }

        for (int ki = 1; ki <= n; ki++) {
            for (int kj = 1; kj <= n; kj++) {
                for (int ii = 1; ii <= n; ii++) {
                    for (int ij = 1; ij <= n; ij++) {
                        for (int ji = 1; ji <= n; ji++) {
                            for (int jj = 1; jj <= n; jj++) {
                                shortestPath[ii][ij][ji][jj] = Math.min(
                                    shortestPath[ii][ij][ji][jj],
                                    shortestPath[ii][ij][ki][kj] + shortestPath[ki][kj][ji][jj]
                                );
                            }
                        }
                    }
                }
            }
        }

        int srcNode = n * n * 2 + 1;
        int sinkNode = n * n * 2 + 2;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (Character.isDigit(scienceMap[i][j])) {
                    capacityMatrix[srcNode][nodeID(i, j, n)] = scienceMap[i][j] - '0';
                }
                if (Character.isDigit(reactionMap[i][j])) {
                    capacityMatrix[n * n + nodeID(i, j, n)][sinkNode] = reactionMap[i][j] - '0';
                }
                if (Character.isDigit(scienceMap[i][j])) {
                    for (int ki = 1; ki <= n; ki++) {
                        for (int kj = 1; kj <= n; kj++) {
                            if (scienceMap[i][j] > '0' && reactionMap[ki][kj] > '0') {
                                if (Character.isDigit(reactionMap[ki][kj]) && shortestPath[i][j][ki][kj] <= tLimit && isReachable(i, j, ki, kj, infX, infY)) {
                                    capacityMatrix[nodeID(i, j, n)][n * n + nodeID(ki, kj, n)] = 1000;
                                }
                            }
                        }
                    }
                }
            }
        }

        int totalFlow = 0, flowVal;
        while ((flowVal = dfsAugment(srcNode, sinkNode, 1000)) > 0) {
            totalFlow += flowVal;
            currentVisit++;
        }

        System.out.println(totalFlow);
    }

    static int nodeID(int x, int y, int n) {
        return (x - 1) * n + y - 1;
    }

    static int dfsAugment(int cnode, int dest, int flow) {
        if (cnode == dest) return flow;
        if (visitedNodes[cnode] == currentVisit) return 0;
        visitedNodes[cnode] = currentVisit;
        for (int i = 0; i <= dest; i++) {
            if (capacityMatrix[cnode][i] > 0) {
                int pushed = dfsAugment(i, dest, Math.min(flow, capacityMatrix[cnode][i]));
                if (pushed > 0) {
                    capacityMatrix[cnode][i] -= pushed;
                    capacityMatrix[i][cnode] += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static boolean isReachable(int sx, int sy, int tx, int ty, int ix, int iy) {
        for (int i = 0; i < 13; i++) {
            Arrays.fill(reachStates[i], 0);
